#!/usr/bin/python3
"""Narrow read-only adjudication of Audit19 retained absolute-checksum notices."""
import argparse
import base64
from datetime import datetime, timezone
import fcntl
import hashlib
import json
import os
from pathlib import Path
import re
import stat
import subprocess
import sys

ARCHIVES = Path('/var/backups/proofofwork-ui/releases')
HELPER = Path('/usr/local/sbin/proofofwork-release-prune')
HELPER_SHA = 'd4de9574cd0c666d198c4d448e72869c09cdfeacd29cd3e1eb0731f0419f8fb6'
PLAN_SHA = '656e92e097f0ce03a14f79edb3743d340f5560d59a2c74aabf153ac7752d97d6'
EVIDENCE_SHA = '8df6aeb1be15dbc22c665b20d1669700d2ede0da93b8b9d3125a0d991eb29b8b'
PREFIX = 'Verified legacy absolute checksum target; normalize deliberately during a future release: '
ORDINARY = {
    'WARNING multiple complete-root UI rollbacks are retained; each root will remain protected while release retention is evaluated.',
    'Multiple complete-root UI rollbacks were validated and excluded from release deletion.',
}
SUMMARY = 'release_retention mode=dry-run verified_archives=5 unverified_archives=0'
COMMAND = [str(HELPER), str(ARCHIVES), '5', '--dry-run']


def sha(data):
    return hashlib.sha256(data).hexdigest()


def pinned_json(data, expected):
    if len(data) > 1024 * 1024 or sha(data) != expected:
        raise ValueError('Reviewed input bytes differ from pinned evidence')
    return json.loads(data)


def classify(result, plan, evidence, current_sidecars=None):
    """Classify only explicit retained paths with exact historical sidecar proof."""
    errors, recognized = [], []
    if result.get('command') != COMMAND or result.get('exit') != 0 or result.get('stdout', '').strip() != SUMMARY:
        errors.append('Command/exit/summary must prove exact keep5 dry-run with zero unverified archives and zero candidates')
    retained = plan.get('remainingArchives', [])
    if len(retained) != 5 or len(set(retained)) != 5:
        errors.append('Expected exactly five reviewed retained archive names')
    records = {row['name']: row for row in evidence.get('archives', [])}
    seen = set()
    for line in result.get('stderr', '').splitlines():
        if not line.strip():
            continue
        if line in seen:
            errors.append('Duplicate retention diagnostic: ' + line)
            continue
        seen.add(line)
        if line in ORDINARY:
            recognized.append({'kind': 'preserved-rollback-notice', 'line': line})
            continue
        if not line.startswith(PREFIX):
            errors.append('Unrecognized retention diagnostic: ' + line)
            continue
        name = line[len(PREFIX):]
        if name not in retained or name not in records:
            errors.append('Legacy checksum notice is not a planned retained archive: ' + name)
            continue
        archive = records[name]
        sidecars = [row for row in archive.get('sidecars', []) if row.get('name') == name + '.sha256']
        if len(sidecars) != 1:
            errors.append('Historical canonical checksum sidecar is missing/ambiguous: ' + name)
            continue
        sidecar = sidecars[0]
        content = sidecar.get('content', '')
        match = re.fullmatch(r'([0-9a-fA-F]{64})  (/var/backups/proofofwork-ui/releases/[^\n]+)\n', content)
        if (not match or match[2] != str(ARCHIVES / name) or match[1].lower() != archive.get('sha256')
                or sha(content.encode()) != sidecar.get('sha256')):
            errors.append('Historical checksum does not bind exact canonical absolute path/digest/bytes: ' + name)
            continue
        if current_sidecars is not None:
            current = current_sidecars.get(name + '.sha256')
            if (not current or current.get('path') != str(ARCHIVES / (name + '.sha256'))
                    or current.get('content') != content or current.get('sha256') != sidecar['sha256']):
                errors.append('Current checksum sidecar differs from preserved historical bytes: ' + name)
                continue
        recognized.append({'kind': 'verified-historical-absolute-checksum', 'archive': name,
                           'archiveSha256': archive['sha256'], 'sidecarSha256': sidecar['sha256'],
                           'absoluteTarget': match[2], 'currentBytesAlsoChecked': current_sidecars is not None})
    return {'status': 'failed' if errors else 'passed-with-known-notices', 'passed': not errors,
            'errors': errors, 'recognizedNotices': recognized,
            'scope': 'read-only classification; no sidecar normalization, production repair or deletion'}


def read_regular(path, limit):
    path = Path(path)
    before = path.lstat()
    if path.resolve() != path or not stat.S_ISREG(before.st_mode) or before.st_uid != 0 or before.st_mode & 0o7022:
        raise ValueError('Unsafe canonical root-owned file: ' + str(path))
    if before.st_size > limit:
        raise ValueError('Read bound exceeded: ' + str(path))
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    identity = lambda value: (value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns, value.st_ctime_ns, value.st_mode, value.st_uid, value.st_gid)
    with os.fdopen(fd, 'rb') as stream:
        if identity(os.fstat(stream.fileno())) != identity(before):
            raise ValueError('File changed before read')
        data = stream.read(limit + 1)
        if len(data) != before.st_size or identity(os.fstat(stream.fileno())) != identity(before) or identity(path.lstat()) != identity(before):
            raise ValueError('File changed during read')
    return data, before


def probe(plan, evidence):
    if os.geteuid() != 0 or not sys.flags.isolated:
        raise ValueError('Probe requires root and isolated Python')
    helper, _ = read_regular(HELPER, 1024 * 1024)
    if sha(helper) != HELPER_SHA:
        raise ValueError('Read-only retention helper differs from reviewed preserved version')
    lock_path = Path('/run/proofofwork-ui/deploy.lock')
    _, lock_stat = read_regular(lock_path, 1024)
    fd = os.open(lock_path, os.O_RDONLY | os.O_NOFOLLOW)
    try:
        if (os.fstat(fd).st_dev, os.fstat(fd).st_ino) != (lock_stat.st_dev, lock_stat.st_ino):
            raise ValueError('Deployment lock changed')
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        checksums = {}
        for name in plan['remainingArchives']:
            data, _ = read_regular(ARCHIVES / (name + '.sha256'), 4096)
            checksums[name + '.sha256'] = {'path': str(ARCHIVES / (name + '.sha256')),
                                          'sha256': sha(data), 'content': data.decode()}
        started = datetime.now(timezone.utc).isoformat()
        result = subprocess.run(['/usr/bin/timeout', '--signal=TERM', '--kill-after=10s', '300', *COMMAND],
                                env={'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LC_ALL': 'C', 'POW_UI_DEPLOY_LOCK_FD': str(fd)},
                                pass_fds=(fd,), capture_output=True, text=True, check=False)
        receipt = {'command': COMMAND, 'exit': result.returncode, 'stdout': result.stdout, 'stderr': result.stderr,
                   'startedAt': started, 'finishedAt': datetime.now(timezone.utc).isoformat()}
        if len(result.stdout) + len(result.stderr) > 1024 * 1024:
            raise ValueError('Retention receipt exceeds 1 MiB bound')
        for name, record in checksums.items():
            data, _ = read_regular(ARCHIVES / name, 4096)
            if sha(data) != record['sha256'] or data.decode() != record['content']:
                raise ValueError('Checksum changed during retention verification')
        helper_after, _ = read_regular(HELPER, 1024 * 1024)
        if sha(helper_after) != HELPER_SHA:
            raise ValueError('Retention helper changed during verification')
        return {'commandReceipt': receipt, 'currentChecksumSidecars': checksums,
                'classification': classify(receipt, plan, evidence, checksums),
                'helperSha256': HELPER_SHA, 'planSha256': PLAN_SHA, 'preparationEvidenceSha256': EVIDENCE_SHA}
    finally:
        os.close(fd)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--probe', action='store_true')
    parser.add_argument('--plan-base64', required=True)
    parser.add_argument('--evidence-base64', required=True)
    parser.add_argument('--classify-receipt', type=Path)
    args = parser.parse_args()
    plan = pinned_json(base64.b64decode(args.plan_base64, validate=True), PLAN_SHA)
    evidence = pinned_json(base64.b64decode(args.evidence_base64, validate=True), EVIDENCE_SHA)
    if args.probe:
        if args.classify_receipt:
            parser.error('Choose probe or local receipt classification')
        report = probe(plan, evidence)
        passed = report['classification']['passed']
    else:
        if not args.classify_receipt:
            parser.error('Specify --probe or --classify-receipt')
        raw = args.classify_receipt.read_bytes()
        original = json.loads(raw)
        result = original.get('commands', {}).get('retention-dry-run', original)
        report = {'originalReceiptSha256': sha(raw), 'originalReceiptPreserved': True,
                  'planSha256': PLAN_SHA, 'preparationEvidenceSha256': EVIDENCE_SHA,
                  'classification': classify(result, plan, evidence)}
        passed = report['classification']['passed']
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0 if passed else 1


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as error:
        print(json.dumps({'status': 'failed', 'error': type(error).__name__ + ': ' + str(error)}))
        raise SystemExit(1)

