#!/usr/bin/env python3
"""Sequential read-only HTML receipts for the UI operations rollout."""
import argparse, datetime, hashlib, json, pathlib, re, time, urllib.error, urllib.parse, urllib.request
BASE = pathlib.Path(__file__).resolve().parent
SURFACES = [('01-home','www'),('02-id','id'),('03-desktop','desktop'),('04-browser','browser'),('05-boost','boost'),('06-amo','amo'),('07-credit','credit'),('08-wallet','wallet'),('09-work','work'),('10-infinity','infinity'),('11-inception','inception'),('12-log','log'),('13-growth','growth'),('14-computer','computer')]
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
class FirstPartyRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, fp, code, message, headers, newurl):
        parsed=urllib.parse.urlsplit(newurl)
        if parsed.scheme!='https' or not (parsed.hostname=='proofofwork.me' or (parsed.hostname or '').endswith('.proofofwork.me')):
            raise ValueError('Refusing redirect outside first-party HTTPS hosts')
        return super().redirect_request(request,fp,code,message,headers,newurl)
parser=argparse.ArgumentParser()
parser.add_argument('phase', choices=['before','after'])
args=parser.parse_args()
receipt={'phase':args.phase,'startedAt':now(),'applicationCommit':'56694a7d6d76de565d4e0a6fce94f880d5308550','concurrency':1,'method':'GET','scope':'14 main HTML documents; Computer last; no API or wallet interaction','results':[]}
output=BASE/(args.phase+'-public-html.json')
if output.exists(): raise SystemExit('Refusing to overwrite an existing observation: '+str(output))
opener=urllib.request.build_opener(FirstPartyRedirect())
for key, host in SURFACES:
    url='https://'+host+'.proofofwork.me/'
    row={'key':key,'url':url,'startedAt':now()}; start=time.monotonic()
    try:
        request=urllib.request.Request(url,headers={'User-Agent':'ProofOfWork-H19-UI-capacity-read-only-verification','Accept':'text/html','Accept-Encoding':'identity','Cache-Control':'no-cache'})
        try: response=opener.open(request,timeout=25)
        except urllib.error.HTTPError as error: response=error
        with response:
            body=response.read(2097153)
            row.update(status=response.status,finalUrl=response.geturl(),contentType=response.headers.get('Content-Type'),cacheControl=response.headers.get('Cache-Control'))
        if len(body)>2097152: raise ValueError('HTML document exceeds 2 MiB verification bound')
        row.update(bytes=len(body),sha256=hashlib.sha256(body).hexdigest())
        html=body.decode('utf-8',errors='replace')
        row['entryAssets']=re.findall(r'(?:src|href)=[\"\'](/assets/[^\"\']+)',html)
